#include <iostream>
using namespace std;

int removeMax(int heap[], int& size) {
    int best = heap[0];
    size--;
    heap[0] = heap[size];
    int i = 0;
    while (true) {
        int largest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        if (left < size && heap[left] > heap[largest]) {
            largest = left;
        }
        if (right < size && heap[right] > heap[largest]) {
            largest = right;
        }
        if (largest == i) {
            break;
        }
        swap(heap[i], heap[largest]);
        i = largest;
    }
    return best;
}

int main() {
    int heap[8] = {50, 30, 40, 10, 20, 35};
    int size = 6;
    cout << "Served first: " << removeMax(heap, size) << endl;
    cout << "Served next: " << removeMax(heap, size) << endl;
    return 0;
}
